import json

# n8n 输入
item = items[0]["json"]

final_output = []

# for entry in item:
merged = {}

# 1. 解析 input（JIRA 原始信息）
if item.get("input"):
    input_str = item["input"][0]
    try:
        input_data = json.loads(input_str)
        merged.update(input_data)
    except Exception:
        merged["raw_input"] = input_str

# 2. 解析 output（problem_causes）
if item.get("output"):
    output_str = item["output"][0]
    try:
        output_data = json.loads(output_str)
        merged["problem_causes"] = output_data.get("problem_causes", [])
    except Exception:
        merged["problem_causes_raw"] = output_str

final_output.append(merged)
final_result_str = json.dumps(merged, ensure_ascii=False, indent=2)
return {
    "final_result": final_output,
    "final_result_str": final_result_str
}
